// The "stand-in class" ES5 adapter from @webcomponents/custom-elements 1.1.3
// (src/native-shim.js). YouTube ships a variant of this older adapter, not the
// Reflect.construct-based one from 1.2+. Three changes match YouTube's copy:
// the `es5Shimmed` marker, the error wrapping in the stand-in constructor, and
// the Safari 10/11.0 `constructor` workaround.
(() => {
  'use strict';
  if (!window.customElements) return;

  const NativeHTMLElement = window.HTMLElement;
  const nativeDefine = window.customElements.define;
  const nativeGet = window.customElements.get;
  const tagnameByConstructor = new Map();
  const constructorByTagname = new Map();
  let browserConstruction = false;
  let userConstruction = false;

  window.HTMLElement = function() {
    if (!browserConstruction) {
      const tagname = tagnameByConstructor.get(this.constructor);
      const fakeClass = nativeGet.call(window.customElements, tagname);
      userConstruction = true;
      return new (fakeClass)();
    }
    browserConstruction = false;
  };
  window.HTMLElement.prototype = NativeHTMLElement.prototype;
  window.HTMLElement['es5Shimmed'] = true;

  const define = (tagname, elementClass) => {
    const elementProto = elementClass.prototype;
    const StandInElement = class extends NativeHTMLElement {
      constructor() {
        super();
        Object.setPrototypeOf(this, elementProto);
        if (!userConstruction) {
          browserConstruction = true;
          try {
            elementClass.call(this);
          } catch (e) {
            throw new Error(`Constructing ${tagname}: ${e}`);
          }
        }
        userConstruction = false;
      }
    };
    const standInProto = StandInElement.prototype;
    StandInElement.observedAttributes = elementClass.observedAttributes;
    standInProto.connectedCallback = elementProto.connectedCallback;
    standInProto.disconnectedCallback = elementProto.disconnectedCallback;
    standInProto.attributeChangedCallback = elementProto.attributeChangedCallback;
    standInProto.adoptedCallback = elementProto.adoptedCallback;
    tagnameByConstructor.set(elementClass, tagname);
    constructorByTagname.set(tagname, elementClass);
    nativeDefine.call(window.customElements, tagname, StandInElement);
  };

  const get = (tagname) => constructorByTagname.get(tagname);

  Object.defineProperty(window, 'customElements',
    {value: window.customElements, configurable: true, writable: true});
  Object.defineProperty(window.customElements, 'define',
    {value: define, configurable: true, writable: true});
  Object.defineProperty(window.customElements, 'get',
    {value: get, configurable: true, writable: true});

  if (navigator.userAgent.match(/Version\/(10\..*|11\.0\..*)Safari/)) {
    const constructor = HTMLElement.prototype.constructor;
    Object.defineProperty(HTMLElement.prototype, 'constructor', {
      configurable: true,
      get() {
        return constructor;
      },
      set(value) {
        Object.defineProperty(this, 'constructor', {value, configurable: true, writable: true});
      },
    });
  }
})();
